{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Rilzabrutinib, the closest analogue sharing the acrylamide-piperidine-pyrazolopyrimidine-phenoxyphenyl core, had an estimated absolute oral bioavailability of only 4.73% in humans after a 400 mg tablet, strongly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Acalabrutinib, a related BTK inhibitor with the same pyrazolopyrimidine core, showed 25% absolute oral bioavailability in healthy subjects, providing limited contradictory evidence that this scaffold can reach the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "Zongertinib, an acrylamide covalent inhibitor with a heteroaromatic core, was predicted to have 41% human oral bioavailability, but its low similarity to the query limits its weight as contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue rilzabrutinib has very low absolute oral bioavailability (~5%) in humans and shares the query's core scaffold and covalent acrylamide warhead. This direct, higher-transferability evidence outweighs weaker high-bioavailability signals from more distant analogues such as acalabrutinib and zongertinib. Therefore, low oral bioavailability (<20%) is predicted for the query, with moderate confidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule in humans or animals.",
    "No fed-state pharmacokinetic data for the query or its closest analogue; rilzabrutinib tablet data may not fully reflect fed conditions.",
    "The closest analogue differs by the absence/presence of the cyano-acrylamide substituent and fluorine, which could alter metabolism and F.",
    "The mechanism of rilzabrutinib's low F (absorption vs first-pass metabolism) is not fully resolved from the records."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C09"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "rilzabrutinib"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C17"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "acalabrutinib"
    },
    {
      "applicability": "low",
      "card_ids": ["C44"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "zongertinib"
    }
  ],
  "revision_action": "initial"
}

